DATA='Linear momentum|p=m*v|p,m,v|s+s|Signed 1D component.|P:1,-m*v;P:-v,p;P:-m,p\nConstant-force impulse|J=F*t|J,F,t|ss0|F constant or average NET force.|P:1,-F*t;P:-t,J;P:-F,J\nImpulse change|J=m*(v-u)|J,m,v,u|s+ss|Constant mass; net external impulse.|P:1,m*u - m*v;P:u - v,J;P:-m,J + m*u;P:m,J - m*v\nStick collision|m1*v1+m2*v2=(m1+m2)*vf|m1,v1,m2,v2,vf|+s+ss|Perfectly inelastic; isolated 1D system.|P:v1 - vf,m2*v2 - m2*vf;P:m1,-m1*vf + m2*v2 - m2*vf;P:v2 - vf,m1*v1 - m1*vf;P:m2,m1*v1 - m1*vf - m2*vf;P:-m1 - m2,m1*v1 + m2*v2\nMomentum balance|m1*u+m2*v=m1*v1+m2*v2|m1,u,m2,v,v1,v2|+s+sss|Signed 1D; negligible external impulse.|P:u - v1,m2*v - m2*v2;P:m1,-m1*v1 + m2*v - m2*v2;P:v - v2,m1*u - m1*v1;P:m2,m1*u - m1*v1 - m2*v2;P:-m1,m1*u + m2*v - m2*v2;P:-m2,m1*u - m1*v1 + m2*v\nCenter of mass 2|x=(m1*x0+m2*dx)/(m1+m2)|x,m1,x0,m2,dx|s+s+s|x0 and dx are the two positions.|P:m1 + m2,-dx*m2 - m1*x0;P:x - x0,-dx*m2 + m2*x;P:-m1,-dx*m2 + m1*x + m2*x;P:-dx + x,m1*x - m1*x0;P:-m2,m1*x - m1*x0 + m2*x'
